-- CampusDesk academic modules upgrade. Safe to re-run.
create table if not exists public.subjects (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, course_id uuid not null references public.courses(id) on delete cascade, name text not null, code text not null, created_at timestamptz not null default now(), unique(user_id,code));
create table if not exists public.teachers (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, full_name text not null, email text not null default '', phone text default '', specialization text default '', created_at timestamptz not null default now());
create table if not exists public.enrollments (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, student_id uuid not null references public.students(id) on delete cascade, course_id uuid not null references public.courses(id) on delete cascade, enrolled_on date not null default current_date, status text not null default 'Active' check(status in ('Active','Completed','Withdrawn')), unique(student_id,course_id));
create table if not exists public.exams (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, course_id uuid not null references public.courses(id) on delete cascade, subject_id uuid references public.subjects(id) on delete set null, title text not null, exam_date date, total_marks numeric(8,2) not null default 100 check(total_marks>0), created_at timestamptz not null default now());
create table if not exists public.results (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, exam_id uuid not null references public.exams(id) on delete cascade, student_id uuid not null references public.students(id) on delete cascade, obtained_marks numeric(8,2) not null check(obtained_marks>=0), remarks text default '', created_at timestamptz not null default now(), unique(exam_id,student_id));
create table if not exists public.fee_records (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, student_id uuid not null references public.students(id) on delete cascade, fee_title text not null default 'Tuition Fee', amount numeric(10,2) not null check(amount>=0), due_date date, paid_amount numeric(10,2) not null default 0 check(paid_amount>=0), paid_on date, status text not null default 'Pending' check(status in ('Pending','Partial','Paid')), notes text default '', created_at timestamptz not null default now(), check(paid_amount<=amount));
create table if not exists public.timetable (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, course_id uuid not null references public.courses(id) on delete cascade, subject_id uuid references public.subjects(id) on delete set null, teacher_id uuid references public.teachers(id) on delete set null, weekday smallint not null check(weekday between 1 and 7), start_time time not null, end_time time not null, room text default '', check(end_time>start_time));
create table if not exists public.user_profiles (user_id uuid primary key references auth.users(id) on delete cascade, display_name text default '', role text not null default 'admin' check(role in ('admin','teacher','student')), linked_student_id uuid references public.students(id) on delete set null, linked_teacher_id uuid references public.teachers(id) on delete set null, created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['subjects','teachers','enrollments','exams','results','fee_records','timetable','user_profiles'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists %I on public.%I','Users manage own '||t,t); execute format('create policy %I on public.%I for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id)','Users manage own '||t,t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); execute format('revoke all on public.%I from anon',t); execute format('create index if not exists %I on public.%I(user_id)',t||'_user_id_idx',t); end loop; end $$;
create index if not exists subjects_course_id_idx on public.subjects(course_id);
create index if not exists enrollments_student_id_idx on public.enrollments(student_id);
create index if not exists exams_course_id_idx on public.exams(course_id);
create index if not exists results_student_id_idx on public.results(student_id);
create index if not exists fee_records_student_id_idx on public.fee_records(student_id);
create index if not exists timetable_course_day_idx on public.timetable(course_id,weekday);

-- Role profiles are deliberately restricted: users cannot promote themselves.
drop policy if exists "Users manage own user_profiles" on public.user_profiles;
create policy "Users read own profile" on public.user_profiles for select to authenticated using ((select auth.uid())=user_id);
create policy "Users create student profile" on public.user_profiles for insert to authenticated with check ((select auth.uid())=user_id and role='student');
create policy "Users update own profile display name" on public.user_profiles for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id and role='student');
revoke all on public.user_profiles from authenticated;
grant select, insert on public.user_profiles to authenticated;
grant update(display_name) on public.user_profiles to authenticated;
